"""Generated card and CSV result presentation."""

from __future__ import annotations

import shutil
import subprocess
from collections.abc import Callable, Iterable
from pathlib import Path

from textual import on
from textual.app import ComposeResult
from textual.containers import Horizontal, Vertical
from textual.widgets import Button, Label, Static

from flashcards_generator.domain.entities import Deck

ResultsAction = Callable[[], None]


class ResultsPanel(Vertical):
    """Present generated cards and provide safe result actions."""

    def __init__(
        self,
        *,
        on_merge: ResultsAction | None = None,
        on_new_generation: ResultsAction | None = None,
        id: str | None = None,
    ) -> None:
        super().__init__(id=id, classes="workflow-panel")
        self._csv_path: Path | None = None
        self._on_merge = on_merge
        self._on_new_generation = on_new_generation

    def compose(self) -> ComposeResult:
        yield Label("Results", classes="workflow-title")
        yield Static("No completed run", id="results-summary")
        yield Static("No generated cards yet", id="results-cards")
        yield Static("No CSV output yet", id="results-csv")
        yield Static("No preview yet", id="results-preview")
        with Horizontal(classes="action-row"):
            yield Button("Copy CSV", id="results-copy")
            yield Button("Open CSV", id="results-open")
            yield Button("Merge", id="results-merge")
            yield Button("New generation", id="results-new")
        yield Static("", id="results-action-status")

    def show_decks(self, decks: Iterable[Deck]) -> None:
        """Render cards without changing the underlying domain models."""
        materialized = tuple(decks)
        lines = self._deck_lines(materialized)
        preview = self._card_preview(materialized)
        self.query_one("#results-cards", Static).update(
            "\n".join(lines) if lines else "No generated cards"
        )
        total_cards = sum(deck.total_cards for deck in materialized)
        self.query_one("#results-summary", Static).update(
            f"{len(materialized)} deck(s), {total_cards} card(s)"
        )
        self.query_one("#results-preview", Static).update(
            "\n".join(preview) if preview else "No card preview"
        )

    @staticmethod
    def _deck_lines(decks: tuple[Deck, ...]) -> list[str]:
        return [f"{deck.name}: {deck.total_cards} card(s)" for deck in decks]

    @staticmethod
    def _card_preview(decks: tuple[Deck, ...]) -> list[str]:
        return [
            f"{card.front} -> {card.back}"
            for deck in decks
            for card in deck.flashcards[:5]
        ]

    def show_csv(self, output_path: Path, rows_written: int) -> None:
        """Render the service-provided output path and row count."""
        self._csv_path = output_path
        self.query_one("#results-csv", Static).update(
            f"{output_path.name} - {rows_written} row(s)"
        )

    def show_csv_paths(self, paths: Iterable[Path]) -> None:
        """Render CSV paths returned by a completed generation."""
        values = tuple(paths)
        if values:
            self._csv_path = values[0]
            self.query_one("#results-csv", Static).update(
                "\n".join(str(path) for path in values)
            )

    def show_generation_summary(
        self,
        *,
        discovered: int,
        completed: int,
        skipped: int,
        failed: int,
        elapsed_seconds: float,
    ) -> None:
        """Render machine-consumable source counts and elapsed time."""
        self.query_one("#results-summary", Static).update(
            f"{completed}/{discovered} source(s), {skipped} skipped, "
            f"{failed} failed, {elapsed_seconds:.1f}s"
        )

    @on(Button.Pressed)
    def on_button_pressed(self, event: Button.Pressed) -> None:
        """Handle result actions without embedding application workflows."""
        button_id = event.button.id
        if self._handle_navigation_action(button_id):
            return
        if button_id == "results-copy":
            self._copy_csv()
        elif button_id == "results-open":
            self._open_csv()

    def _handle_navigation_action(self, button_id: str | None) -> bool:
        actions = {
            "results-merge": self._on_merge,
            "results-new": self._on_new_generation,
        }
        if button_id not in actions:
            return False
        action = actions[button_id]
        if action is not None:
            self.call_after_refresh(action)
        return True

    def _copy_csv(self) -> None:
        if self._csv_path is None:
            self._set_action_status("No CSV available")
            return
        arguments = self._clipboard_arguments()
        if arguments is None:
            self._set_action_status("Clipboard command unavailable")
            return
        try:
            subprocess.run(
                arguments,
                input=self._csv_path.read_text(encoding="utf-8"),
                text=True,
                check=False,
                timeout=5,
            )
        except (OSError, subprocess.SubprocessError):
            self._set_action_status("Unable to copy CSV")
        else:
            self._set_action_status("CSV copied")

    @staticmethod
    def _clipboard_arguments() -> list[str] | None:
        command = shutil.which("wl-copy") or shutil.which("xclip")
        if command is None:
            return None
        arguments = [command]
        if command.endswith("xclip"):
            arguments.extend(["-selection", "clipboard"])
        return arguments

    def _open_csv(self) -> None:
        if self._csv_path is None:
            self._set_action_status("No CSV available")
            return
        opener = shutil.which("xdg-open")
        if opener is None:
            self._set_action_status("xdg-open unavailable")
            return
        try:
            subprocess.run(
                [opener, str(self._csv_path)],
                check=False,
                timeout=5,
            )
        except (OSError, subprocess.SubprocessError):
            self._set_action_status("Unable to open CSV")
        else:
            self._set_action_status("Open command sent")

    def _set_action_status(self, message: str) -> None:
        self.query_one("#results-action-status", Static).update(message)

"""NotebookLM authentication and cleanup controls."""

from __future__ import annotations

from typing import Literal, cast

from textual.app import ComposeResult
from textual.containers import Horizontal, Vertical
from textual.widgets import Button, Input, Label, Static
from textual.worker import Worker, WorkerState

from flashcards_generator.application.dto.workflow import (
    AuthStatus,
    CleanupOutcome,
)
from flashcards_generator.interfaces.tui.contracts import WorkflowServices

ManagementResult = AuthStatus | CleanupOutcome | bool
ManagementOperation = Literal["status", "login", "cleanup", "language"]


class CleanupConfirmation(Vertical):
    """Explicit destructive-action confirmation surface."""

    def compose(self) -> ComposeResult:
        yield Label(
            "Delete every NotebookLM notebook?", classes="section-title"
        )
        yield Static("This action cannot be undone.")
        with Horizontal(classes="action-row"):
            yield Button(
                "Delete all",
                id="confirm-cleanup-all",
                variant="error",
            )
            yield Button("Keep notebooks", id="cancel-cleanup-all")


class NotebookLMPanel(Vertical):
    """Delegate provider management through an injected service boundary."""

    def __init__(
        self,
        services: WorkflowServices | None = None,
        *,
        id: str | None = None,
    ) -> None:
        super().__init__(id=id, classes="workflow-panel")
        self.services = services
        self._operation: ManagementOperation | None = None
        self._worker: Worker[ManagementResult] | None = None

    def compose(self) -> ComposeResult:
        yield Label("NotebookLM", classes="workflow-title")
        yield Static("Authentication not checked", id="notebooklm-auth-status")
        yield Label("Output language", classes="field-label")
        yield Input("pt_BR", id="notebooklm-language")
        with Horizontal(classes="action-row"):
            yield Button("Refresh", id="notebooklm-refresh")
            yield Button("Login", id="notebooklm-login", variant="primary")
            yield Button("Set language", id="notebooklm-set-language")
            yield Button(
                "Cleanup all",
                id="notebooklm-cleanup-all",
                variant="error",
            )
        yield Vertical(id="notebooklm-confirmation-slot")

    async def on_button_pressed(self, event: Button.Pressed) -> None:
        button_id = event.button.id
        if await self._handle_confirmation_button(button_id):
            return
        operations: dict[str | None, ManagementOperation] = {
            "notebooklm-refresh": "status",
            "notebooklm-login": "login",
            "notebooklm-set-language": "language",
        }
        operation = operations.get(button_id)
        if operation is not None:
            self._run(operation)

    async def _handle_confirmation_button(self, button_id: str | None) -> bool:
        if button_id == "notebooklm-cleanup-all":
            await self._show_cleanup_confirmation()
            return True
        if button_id == "cancel-cleanup-all":
            await self._clear_confirmation()
            return True
        if button_id == "confirm-cleanup-all":
            await self._clear_confirmation()
            self._run("cleanup")
            return True
        return False

    def _run(self, operation: ManagementOperation) -> None:
        if self.services is None:
            return
        self._operation = operation
        self.query_one("#notebooklm-auth-status", Static).update(
            "Checking" if operation == "status" else f"Running {operation}"
        )
        service = self.services

        def invoke() -> ManagementResult:
            if operation == "status":
                return service.auth_status()
            if operation == "login":
                return service.login()
            if operation == "language":
                return service.set_language(
                    self.query_one("#notebooklm-language", Input).value
                )
            return service.cleanup_all(confirmed=True)

        self._worker = self.run_worker(
            invoke,
            name=f"notebooklm-{operation}",
            group="notebooklm",
            thread=True,
            exclusive=True,
            exit_on_error=False,
        )

    def on_worker_state_changed(self, event: Worker.StateChanged) -> None:
        if event.worker is not self._worker:
            return
        status = self.query_one("#notebooklm-auth-status", Static)
        if event.state is WorkerState.ERROR:
            status.update(f"{self._operation or 'operation'} failed")
        elif event.state is WorkerState.SUCCESS:
            self._show_result(status, event.worker)

    @staticmethod
    def _show_result(status: Static, worker: Worker[ManagementResult]) -> None:
        result = cast(ManagementResult, worker.result)
        if isinstance(result, AuthStatus):
            status.update(result.message)
        elif isinstance(result, CleanupOutcome):
            status.update(
                f"Cleanup complete: {result.deleted} deleted, "
                f"{result.failed} failed"
            )
        else:
            status.update(
                "Language saved" if result else "Language update failed"
            )

    async def _show_cleanup_confirmation(self) -> None:
        slot = self.query_one("#notebooklm-confirmation-slot", Vertical)
        if not slot.query("#cleanup-confirm"):
            await slot.mount(CleanupConfirmation(id="cleanup-confirm"))

    async def _clear_confirmation(self) -> None:
        slot = self.query_one("#notebooklm-confirmation-slot", Vertical)
        await slot.remove_children()

